+function segmentToRegex(seg: string): string {
+  let out = "";
+  for (let i = 0; i < seg.length; i++) {
+    const ch = seg[i];
+    if (ch === "*") {
+      if (i + 1 < seg.length && seg[i + 1] === "*") {
+        out += "[^/]*";
+        i++;
+      } else {
+        out += "[^/]*";
+      }
+    } else if (ch === "?") {
+      out += "[^/]";
+    } else if ("\\^$.|+()[]{}".includes(ch)) {
+      out += "\\" + ch;
+    } else {
+      out += ch;
+    }
+  }
+  return out;
+}
+
+function patternToRegex(pattern: string): { source: string; negate: boolean } {
+  let negate = false;
+  if (pattern.startsWith("!")) {
+    negate = true;
+    pattern = pattern.substring(1);
+  }
+
+  const segs = pattern.split("/");
+  let source = "^";
+  let prevStarStar = false;
+
+  for (let i = 0; i < segs.length; i++) {
+    const seg = segs[i];
+
+    if (seg === "**") {
+      if (segs.length === 1) {
+        source += ".*";
+      } else if (i === 0) {
+        source += "([^/]+/)*";
+      } else if (i === segs.length - 1) {
+        source += "/.*";
+      } else {
+        source += "/([^/]+/)*";
+      }
+      prevStarStar = true;
+    } else {
+      if (i > 0 && !prevStarStar) source += "/";
+      prevStarStar = false;
+      source += segmentToRegex(seg);
+    }
+  }
+
+  source += "$";
+  return { source, negate };
+}
+
+interface CompiledPattern {
+  original: string;
+  regex: RegExp;
+  negate: boolean;
+}
+
